// Resolve2AE V1.0.1
app.beginUndoGroup('Import Resolve Clips');
var comp = app.project.items.addComp('Link_Timeline_single_1700000000', 1920, 1080, 1, 1.0, 24.0);
comp.openInViewer();
// Clip: ClipFX
var fileItem = null;
for (var k=1; k<=app.project.items.length; k++) { if (app.project.items[k].file && app.project.items[k].file.fsName == 'C:/media/clip.mov') { fileItem = app.project.items[k]; break; } }
if (!fileItem) { fileItem = app.project.importFile(new ImportOptions(File('C:/media/clip.mov'))); }
if (fileItem.mainSource && fileItem.mainSource.nativeFrameRate) { fileItem.mainSource.conformFrameRate = fileItem.mainSource.nativeFrameRate; }
var layer = comp.layers.add(fileItem);
layer.name = 'ClipFX';
layer.audioEnabled = false;
layer.startTime = 0.0 - 0.0;
layer.inPoint = 0.0;
layer.outPoint = 1.0;
try { layer.blendingMode = BlendingMode.NORMAL; } catch(e) {}
layer.opacity.setValue(100.0);
var compW = 1920.0;
var compH = 1080.0;
var srcW = layer.width;
var srcH = layer.height;
var s = 1.0;
var r_pan = 0.1;
var r_tilt = -0.2;
var r_ancX = 0.05;
var r_ancY = -0.03;
var isNormPan = (Math.abs(r_pan) <= 4.0);
var isNormTilt = (Math.abs(r_tilt) <= 4.0);
var isNormAncX = (Math.abs(r_ancX) <= 4.0);
var isNormAncY = (Math.abs(r_ancY) <= 4.0);
var panPx = isNormPan ? (r_pan * compW) : r_pan;
var tiltPx = isNormTilt ? (r_tilt * compH) : r_tilt;
var ancOffsetX = isNormAncX ? (r_ancX * compW) : r_ancX;
var ancOffsetY = isNormAncY ? (r_ancY * compH) : r_ancY;
var ae_ancX = (srcW / 2) + (1) * (ancOffsetX / s);
var ae_ancY = (srcH / 2) + (-1) * (ancOffsetY / s);
layer.property('Anchor Point').setValue([ae_ancX, ae_ancY]);
var ae_posX = (compW / 2) + panPx + ancOffsetX;
var ae_posY = (compH / 2) - tiltPx - ancOffsetY;
layer.property('Position').setValue([ae_posX, ae_posY]);
layer.property('Scale').setValue([1.2 * s * 100 * 1, 0.9 * s * 100 * 1]);
layer.property('Rotation').setValue(-5.0);
// Crop Mask
var hvw = compW / (2 * s);
var hvh = compH / (2 * s);
var cx = srcW / 2, cy = srcH / 2;
var ml = cx - hvw + 0.1 * compW / s;
var mr = cx + hvw - 0.05 * compW / s;
var mt = cy - hvh + 0.02 * compH / s;
var mb = cy + hvh - 0.03 * compH / s;
var cropMask = layer.Masks.addProperty('Mask');
cropMask.maskMode = MaskMode.ADD;
var cropShape = new Shape();
cropShape.vertices = [[ml,mt],[mr,mt],[mr,mb],[ml,mb]];
cropShape.closed = true;
cropMask.property('maskShape').setValue(cropShape);
// Lens Correction -> Optics Compensation
try {
  var optics = layer.Effects.addProperty('Optics Compensation');
  optics(1).setValue(52.46600638277029);
  optics(2).setValue(true);
} catch(e) {}
app.endUndoGroup();
var jsxFile = new File($.fileName);
if (jsxFile.exists) jsxFile.remove();
